CREATE TABLE tax_profiles (
 user_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 name VARCHAR(64) NOT NULL,
 sex VARCHAR(16) NOT NULL,
 birth CHAR(10) NOT NULL,
 card_type VARCHAR(64) NOT NULL,
 id_card VARCHAR(64) NOT NULL,
 phone VARCHAR(20) NOT NULL DEFAULT '',
 email VARCHAR(254) NOT NULL DEFAULT '',
 tax_number VARCHAR(64) NOT NULL,
 bank_num VARCHAR(64) NOT NULL,
 refund2019 DECIMAL(20,2) NOT NULL DEFAULT 0,
 refund2020 DECIMAL(20,2) NOT NULL DEFAULT 0,
 refund2021 DECIMAL(20,2) NOT NULL DEFAULT 0,
 refund2022 DECIMAL(20,2) NOT NULL DEFAULT 0,
 refund2023 DECIMAL(20,2) NOT NULL DEFAULT 0,
 huji_city VARCHAR(128) NOT NULL,
 huji_address VARCHAR(255) NOT NULL,
 usually_city VARCHAR(128) NOT NULL,
 usually_address VARCHAR(255) NOT NULL,
 contact_city VARCHAR(128) NOT NULL,
 contact_address VARCHAR(255) NOT NULL,
 education VARCHAR(64) NOT NULL,
 nation VARCHAR(64) NOT NULL,
 country VARCHAR(64) NOT NULL,
 version VARCHAR(32) NOT NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 CONSTRAINT fk_tax_profile_user FOREIGN KEY(user_id) REFERENCES users(id),
 KEY idx_tax_profile_updated(updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE tax_profile_audits (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT UNSIGNED NOT NULL,
 admin_id BIGINT UNSIGNED NULL,
 action VARCHAR(24) NOT NULL,
 before_payload JSON NULL,
 after_payload JSON NULL,
 created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 KEY idx_tax_profile_audit_user(user_id,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
